using System.Text;using System.Text.Json;namespace QuantForge.Core;public sealed class AndroidTestChecklistFileStore{private readonly string _path;public AndroidTestChecklistFileStore(string path)=>_path=Path.GetFullPath(path);public void Save(IReadOnlyList<AndroidTestChecklistItem> value){if(value.Count==0)throw new InvalidOperationException("Android test checklist cannot be empty.");Directory.CreateDirectory(Path.GetDirectoryName(_path)!);File.WriteAllText(_path,JsonSerializer.Serialize(value,new JsonSerializerOptions{WriteIndented=true}),new UTF8Encoding(false));}public IReadOnlyList<AndroidTestChecklistItem> Load()=>JsonSerializer.Deserialize<AndroidTestChecklistItem[]>(File.ReadAllText(_path))??throw new InvalidOperationException("Android test checklist JSON is invalid.");}
